from taf.ul.teb import teb  # type: ignore
from taf.ul.sc.perf.tc import tc
from taf.ul.sc.perf.post import db_markers
from taf.ul.sc.perf.util.logger import log_debug_function_info, log_function_status_to_console


class TestResultsValidationInterface(object):

    @log_function_status_to_console(msg="Validating test results", log_hierarchy=2, ignore_exception=True)
    @log_debug_function_info()
    def validate_test_results(self):
        if tc.is_feature_enabled("validate_test_results->TEB") and tc.is_feature_enabled("add_results_to_database"):
            results = self._validate_test_results_via_teb(teb_execution_id=tc.database_id)
            status = results.get('status')
            db_markers.add_url_validation_link(results['content'][str(tc.database_id)]['validation_link'])
        else:
            status = self._validate_test_results_via_taf()

        test_status = 'PASSED' if status else 'FAILED'
        db_markers.add_test_status(test_status)

        return test_status

    @staticmethod
    def _validate_test_results_via_teb(teb_execution_id):
        validation_policies = tc.run_params['validate_test_results']['TEB']['validation_policies']
        status = teb().validate(teb_ids=[teb_execution_id],
                                database_url=tc.run_params['environment']['teb_url'],
                                validation_policies=validation_policies)
        return status

    @staticmethod
    def _validate_test_results_via_taf():
        pass
